// warmup.mjs - evaluated once, before any importer's body
const pool = await createPool({ min: 8 });   // top-level await
await pool.ping();                           // validated before export
export const db = pool;                      // consumers never acquire

// eager by construction: the executor runs now, not on the first .then()
export const ready = fetch('/warmup').then((r) => r.ok);
